'use strict';
/* Tasks, productivity and operations (M-OPS) - replaces Zoho Projects */

const TASK_ST = [['todo', 'To do'], ['doing', 'In progress'], ['review', 'In review'], ['done', 'Done']];
const PRIORITIES = ['Low', 'Medium', 'High', 'Urgent'];
const stLabel = s => (TASK_ST.find(x => x[0] === s) || [s, s])[1];
const WORK_TABS = [{ k: 'tasks', l: 'Tasks' }, { k: 'board', l: 'Board' }, { k: 'calendar', l: 'Calendar' }, { k: 'gantt', l: 'Timeline' }, { k: 'projects', l: 'Projects' }, { k: 'templates', l: 'Project templates' }, { k: 'recurring', l: 'Recurring tasks' }, { k: 'sitedev', l: 'Estate development' }, { k: 'assets', l: 'Company assets' }, { k: 'issues', l: 'Issues' }, { k: 'facility', l: 'Facility requests' }, { k: 'timesheets', l: 'Timesheets' }, { k: 'workload', l: 'Workload' }, { k: 'reports', l: 'Reports' }];
function visibleTasks() { const u = SESS.uid; if (can('task.manage') || can('read.all')) return DB.q('tasks'); const myPrj = DB.q('projects').filter(p => (p.team || []).includes(u) || p.owner === u).map(p => p.id); return DB.q('tasks').filter(t => t.assignee === u || (t.followers || []).includes(u) || t.cby === u || myPrj.includes(t.project)); }
const taskRow = t => ({ ...t, projectName: DB.get('projects', t.project)?.name || '—', assigneeName: userName(t.assignee), overdue: t.status !== 'done' && t.due && t.due < today() });

PAGES.work = (parts, q) => {
  const tab = parts[0] || 'tasks'; if (tab === 'project') return projectPage(parts[1]);
  const open = visibleTasks().filter(t => t.status !== 'done'); const over = open.filter(t => t.due && t.due < today());
  let body = ''; if (tab === 'tasks') body = workList(); else if (tab === 'board') body = workBoard(); else if (tab === 'calendar') body = workCalendar(); else if (tab === 'gantt') body = workGantt(); else if (tab === 'projects') body = workProjects(); else if (tab === 'templates') body = workTemplates(); else if (tab === 'recurring') body = workRecurring(); else if (tab === 'sitedev') body = workSiteDev(); else if (tab === 'assets') body = workAssets(); else if (tab === 'issues') body = workIssues(); else if (tab === 'facility') body = workFacility(); else if (tab === 'timesheets') body = workTimesheets(); else if (tab === 'workload') body = workLoad(); else if (tab === 'reports') body = workReports();
  openFromQuery('t', id => openTask(id)); openFromQuery('i', id => openIssue(id)); openFromQuery('f', id => openFacility(id));
  return pageHead({ title: `Tasks${pi('clipboard', true)}and projects`, sub: `${open.length} open · ${over.length} overdue · ${DB.q('projects').filter(p => !p.template && p.status === 'Active').length} active projects`, acts: `<button class="btn primary" data-act="task.new">${icon('plus', 'sm')} New task</button>` }) + tabs('work', WORK_TABS, tab) + body;
};

/* ----- list (OPS-03) ----- */
function workList() {
  const mine = UI.taskMine;
  const rows = () => visibleTasks().filter(t => !UI.taskMine || t.assignee === SESS.uid).map(taskRow);
  return `<div class="row" style="margin-bottom:12px"><div class="row" style="gap:4px"><button class="btn sm ${!mine ? 'dark' : ''}" data-act="task.mine" data-v="">All visible</button><button class="btn sm ${mine ? 'dark' : ''}" data-act="task.mine" data-v="1">Assigned to me</button></div></div>` + table({ id: 'tasks', title: 'Tasks', rows, ph: 'Search tasks', sort: { k: 'due', dir: 1 }, onRow: t => openTask(t.id), filters: [{ k: 'status', l: 'Status', o: TASK_ST, get: t => t.status }, { k: 'priority', l: 'Priority', o: PRIORITIES, get: t => t.priority }, { k: 'project', l: 'Project', o: DB.q('projects').filter(p => !p.template).map(p => [p.id, p.name]), get: t => t.project }, { k: 'assignee', l: 'Assignee', o: coUsers().map(u => [u.id, u.name]), get: t => t.assignee }], bulk: [{ l: 'Mark done', f: ids => { ids.forEach(i => setTaskStatus(i, 'done')); TBL.tasks.sel.clear(); render(); } }, { l: 'Assign to…', f: ids => openForm({ title: 'Assign ' + ids.length + ' tasks', fields: [{ n: 'a', l: 'Assignee', t: 'select', req: true, o: coUsers().map(u => [u.id, u.name]) }], onSubmit: v => { ids.forEach(i => { DB.set('tasks', i, { assignee: v.a }, { action: 'assign' }); notify(v.a, 'Task assigned to you', DB.get('tasks', i).title, '#/work/tasks?t=' + i); }); TBL.tasks.sel.clear(); render(); } }) }], cols: [{ k: 'title', l: 'Task', r: t => `<div class="cellmain"><b>${esc(t.title)}</b><span>${esc(t.projectName)}${t.link ? ' · linked ' + esc(t.link.type) : ''}${t.recur ? ' · repeats ' + esc(t.recur.freq) : ''}</span></div>`, x: t => t.title }, { k: 'assigneeName', l: 'Assignee', r: t => userChip(t.assignee), x: t => t.assigneeName }, { k: 'due', l: 'Due', r: t => t.due ? `<span style="${t.overdue ? 'color:var(--harvest)' : ''}">${fmtDate(t.due)}${t.overdue ? ' · overdue' : ''}</span>` : '—', sv: t => t.due || '9' }, { k: 'priority', l: 'Priority', r: t => spill(t.priority), sv: t => PRIORITIES.indexOf(t.priority) }, { k: 'status', l: 'Status', r: t => spill(stLabel(t.status), t.status === 'done' ? 'ok' : t.status === 'doing' ? 'warn' : t.status === 'review' ? 'info' : ''), x: t => stLabel(t.status) }] });
}
ACT['task.mine'] = el => { UI.taskMine = el.dataset.v; render(); };
function setTaskStatus(id, st) {
  const t = DB.get('tasks', id); if (!t || t.status === st) return;
  if (st === 'done' && (t.deps || []).some(d => DB.get('tasks', d) && DB.get('tasks', d).status !== 'done')) return toast('Finish the tasks this one depends on first.', 'warn');
  const hist = (t.history || []).concat([{ ts: Date.now(), by: SESS.uid, what: 'Status ' + stLabel(t.status) + ' → ' + stLabel(st) }]);
  DB.set('tasks', id, { status: st, history: hist, doneAt: st === 'done' ? Date.now() : null }, { action: 'status' });
  if (st === 'done' && t.assignee !== SESS.uid) notify(t.cby && t.cby !== SESS.uid ? t.cby : t.assignee, 'Task completed: ' + t.title, userName(SESS.uid), '#/work/tasks?t=' + id);
  (t.followers || []).filter(f => f !== SESS.uid).forEach(f => notify(f, 'Task ' + stLabel(st).toLowerCase() + ': ' + t.title, '', '#/work/tasks?t=' + id));
  if (t.link?.type === 'rltstall') { }
}
const taskFields = (t = {}) => [{ n: 'title', l: 'Task', req: true }, { n: 'desc', l: 'Description', t: 'textarea' }, { n: 'project', l: 'Project', t: 'select', o: DB.q('projects').filter(p => !p.template).map(p => [p.id, p.name]), blank: 'No project', half: true }, { n: 'assignee', l: 'Assignee', t: 'select', req: true, o: coUsers().filter(u => u.role !== 'auditor').map(u => [u.id, u.name]), blank: false, half: true }, { n: 'start', l: 'Start', t: 'date', half: true }, { n: 'due', l: 'Due', t: 'date', half: true }, { n: 'priority', l: 'Priority', t: 'select', blank: false, o: PRIORITIES, half: true }, { n: 'est', l: 'Estimate (hours)', t: 'number', min: 0, half: true }];
ACT['task.new'] = el => { const lt = el?.dataset?.linkType, li = el?.dataset?.linkId; openForm({ title: 'New task', fields: taskFields(), draft: 'task-new', vals: { assignee: SESS.uid, priority: 'Medium', due: addDays(today(), 3) }, onSubmit: v => { const t = DB.add('tasks', { ...v, followers: [], status: 'todo', subtasks: [], checklist: [], comments: [], history: [{ ts: Date.now(), by: SESS.uid, what: 'Created task' }], deps: [], link: lt ? { type: lt, id: li } : null }); if (v.assignee !== SESS.uid) notify(v.assignee, 'Task assigned to you: ' + v.title, userName(SESS.uid), '#/work/tasks?t=' + t.id); toast('Task created'); render(); } }); };
function linkLabel(l) { if (!l) return ''; const m = { lead: ['leads', 'crm/leads?l='], client: ['clients', 'crm/client/'], sale: ['sales', 'crm/sales?s='], realtor: ['realtors', 'realtors/pipeline?r='], ticket: ['tickets', 'cx/tickets?t='], employee: ['employees', 'hr/directory?e='], facility: ['facilityreqs', 'work/facility?f='], report: ['reports', 'reports/'] }[l.type]; if (!m) return ''; const rec = DB.get(m[0], l.id); const name = rec ? (rec.name || rec.no || rec.subject || rec.dept) : l.type; return `<a href="#/${m[1]}${l.id}" data-act="ov.close">${esc(l.type)} · ${esc(name)}</a>`; }
function openTask(id) {
  openDrawer(() => {
    const t = DB.get('tasks', id); if (!t) return null; const prj = DB.get('projects', t.project); const manage = can('task.manage') || t.assignee === SESS.uid || t.cby === SESS.uid; const mine = DB.q('timelogs').filter(l => l.taskId === id); const timer = me().timer; const running = timer && timer.taskId === id;
    const fields = [{ n: 'title', l: 'Task' }, { n: 'desc', l: 'Description', t: 'textarea' }, { n: 'status', l: 'Status', t: 'select', blank: false, o: TASK_ST, half: true }, { n: 'priority', l: 'Priority', t: 'select', blank: false, o: PRIORITIES, half: true }, { n: 'assignee', l: 'Assignee', t: 'select', blank: false, o: coUsers().filter(u => u.role !== 'auditor').map(u => [u.id, u.name]), half: true }, { n: 'project', l: 'Project', t: 'select', o: DB.q('projects').filter(p => !p.template).map(p => [p.id, p.name]), blank: 'No project', half: true }, { n: 'start', l: 'Start', t: 'date', half: true }, { n: 'due', l: 'Due', t: 'date', half: true }, { n: 'est', l: 'Estimate (hours)', t: 'number', min: 0, half: true }, { n: 'followers', l: 'Followers', t: 'multi', o: coUsers().filter(u => u.role !== 'auditor').map(u => [u.id, u.name.split(' ')[0]]) }];
    return { title: esc(t.title), body: `<div class="row wrap" style="margin-bottom:12px">${spill(stLabel(t.status), t.status === 'done' ? 'ok' : t.status === 'doing' ? 'warn' : '')}${spill(t.priority)}${t.link ? `<span class="tag">${linkLabel(t.link)}</span>` : ''}${t.auto ? `<span class="tag">Auto-created</span>` : ''}${t.recur ? `<span class="tag">${icon('refresh', 'sm')} Repeats ${esc(t.recur.freq)}</span>` : ''}</div>
    ${manage ? autoForm('tasks', id, fields, t) : kv([['Assignee', esc(userName(t.assignee))], ['Due', fmtDate(t.due)], ['Description', esc(t.desc || '—')]])}
    <div class="sec"><h4>Subtasks</h4>${(t.subtasks || []).map((s, i) => `<label class="row" style="gap:10px;padding:3px 0"><input type="checkbox" data-act="sub.toggle" data-id="${id}" data-i="${i}" data-kind="subtasks" ${s.done ? 'checked' : ''}><span class="grow" style="${s.done ? 'text-decoration:line-through;color:var(--muted)' : ''}">${esc(s.t)}</span></label>`).join('') || '<span class="muted small">None.</span>'}<form class="row" style="margin-top:6px" data-submit="sub.add" data-id="${id}" data-kind="subtasks"><label class="chip grow"><input name="t" placeholder="Add subtask" aria-label="Add subtask"></label></form></div>
    <div class="sec"><h4>Checklist</h4>${(t.checklist || []).map((s, i) => `<label class="row" style="gap:10px;padding:3px 0"><input type="checkbox" data-act="sub.toggle" data-id="${id}" data-i="${i}" data-kind="checklist" ${s.done ? 'checked' : ''}><span class="grow" style="${s.done ? 'text-decoration:line-through;color:var(--muted)' : ''}">${esc(s.t)}</span></label>`).join('') || '<span class="muted small">None.</span>'}<form class="row" style="margin-top:6px" data-submit="sub.add" data-id="${id}" data-kind="checklist"><label class="chip grow"><input name="t" placeholder="Add checklist item" aria-label="Add checklist item"></label></form></div>
    <div class="sec"><h4>Dependencies and repeat</h4><div class="row wrap"><button class="btn sm" data-act="task.deps" data-id="${id}">${icon('link', 'sm')} ${(t.deps || []).length ? (t.deps.length + ' dependenc' + (t.deps.length > 1 ? 'ies' : 'y')) : 'Set dependencies'}</button><button class="btn sm" data-act="task.recur" data-id="${id}">${icon('refresh', 'sm')} ${t.recur ? 'Change repeat' : 'Make recurring'}</button></div>${(t.deps || []).map(d => { const x = DB.get('tasks', d); return x ? `<div class="small muted" style="margin-top:4px">After: ${esc(x.title)} (${stLabel(x.status)})</div>` : ''; }).join('')}</div>
    <div class="sec"><h4>Time</h4><div class="row wrap"><b style="font-weight:500">${Math.round(sum(mine, l => l.hours) * 10) / 10} h logged</b>${t.est ? `<span class="muted small">of ${t.est} h estimated</span>` : ''}<span class="sp"></span>${running ? `<button class="btn sm dark" data-act="timer.stop">${icon('clock', 'sm')} Stop timer</button>` : `<button class="btn sm" data-act="timer.start" data-id="${id}">${icon('clock', 'sm')} Start timer</button>`}<button class="btn sm" data-act="time.add" data-id="${id}">Add time</button></div></div>
    <div class="sec"><h4>Attachments</h4>${(t.files || []).map(f => `<a class="tag" href="${f.url}" download="${esc(f.name)}">${icon('clip', 'sm')} ${esc(f.name)}</a>`).join(' ') || '<span class="muted small">None.</span>'} <button class="btn sm" data-act="task.attach" data-id="${id}">Attach file</button></div>
    <div class="sec"><h4>Comments</h4><div class="stack" style="gap:10px">${(t.comments || []).map(c => `<div class="row" style="align-items:flex-start">${avatar(userName(c.by), 'sm')}<div><b style="font-weight:500">${esc(userName(c.by))}</b> <span class="small muted">${ago(c.ts)}</span><div style="white-space:pre-wrap">${mentionHtml(c.text)}</div></div></div>`).join('') || '<span class="muted small">No comments yet.</span>'}</div><form style="margin-top:10px" data-submit="task.comment" data-id="${id}"><label class="chip" style="width:100%"><input name="t" placeholder="Write a comment. Use @name to mention someone" aria-label="Comment"></label></form></div>
    <div class="sec"><h4>Activity</h4><div class="tl">${(t.history || []).slice().reverse().slice(0, 12).map(h => `<div class="it">${esc(h.what)}<br><span class="small muted">${esc(userName(h.by))} · ${fmtDT(h.ts)}</span></div>`).join('')}</div></div>`, foot: `${t.status !== 'done' && manage ? `<button class="btn primary" data-act="task.done" data-id="${id}">${icon('check', 'sm')} Mark done</button>` : ''}${manage ? `<button class="btn danger" data-act="task.del" data-id="${id}">Delete</button>` : ''}` };
  }, { wide: true });
}
const mentionHtml = s => esc(s).replace(/@([A-Za-z][\w-]*(?: [A-Z][\w-]*)?)/g, '<span class="mn" style="background:var(--tea);border-radius:6px;padding:0 4px;color:var(--deep)">@$1</span>');
function mentionIds(text) { return coUsers().filter(u => { const first = u.name.split(' ')[0]; return text.includes('@' + u.name) || new RegExp('@' + first + '\\b').test(text); }).map(u => u.id); }
ACT['task.done'] = el => { setTaskStatus(el.dataset.id, 'done'); render(); };
ACT['task.del'] = el => confirmDlg('Move this task to the recycle bin?', () => { DB.del('tasks', el.dataset.id); closeAllOverlays(); render(); }, { danger: true, yes: 'Delete' });
ACT['sub.toggle'] = el => { const t = DB.get('tasks', el.dataset.id); const l = (t[el.dataset.kind] || []).map((x, i) => i == el.dataset.i ? { ...x, done: el.checked } : x); DB.set('tasks', t.id, { [el.dataset.kind]: l }, { quiet: true }); refreshOverlays(); };
ACT['sub.add'] = f => { const v = f.t.value.trim(); if (!v) return; const t = DB.get('tasks', f.dataset.id); DB.set('tasks', t.id, { [f.dataset.kind]: (t[f.dataset.kind] || []).concat([{ t: v, done: false }]) }, { quiet: true }); refreshOverlays(); };
ACT['task.comment'] = f => { const v = f.t.value.trim(); if (!v) return; const t = DB.get('tasks', f.dataset.id); DB.set('tasks', t.id, { comments: (t.comments || []).concat([{ by: SESS.uid, ts: Date.now(), text: v }]), history: (t.history || []).concat([{ ts: Date.now(), by: SESS.uid, what: 'Commented' }]) }, { quiet: true }); mentionIds(v).filter(i => i !== SESS.uid).forEach(i => notify(i, userName(SESS.uid) + ' mentioned you', t.title + ': ' + v.slice(0, 80), '#/work/tasks?t=' + t.id)); [t.assignee, ...(t.followers || [])].filter(i => i && i !== SESS.uid && !mentionIds(v).includes(i)).forEach(i => notify(i, 'New comment on ' + t.title, v.slice(0, 80), '#/work/tasks?t=' + t.id)); refreshOverlays(); };
ACT['task.attach'] = el => openForm({ title: 'Attach file', fields: [{ n: 'file', l: 'File', t: 'file', req: true }], onSubmit: v => { const t = DB.get('tasks', el.dataset.id); DB.set('tasks', t.id, { files: (t.files || []).concat([{ name: v.file_name || 'file', url: v.file }]) }, { quiet: true }); refreshOverlays(); } });
ACT['task.deps'] = el => { const t = DB.get('tasks', el.dataset.id); openForm({ title: 'Task depends on', vals: { deps: t.deps || [] }, fields: [{ n: 'deps', l: 'This task can finish only after', t: 'multi', o: DB.q('tasks').filter(x => x.id !== t.id && (!t.project || x.project === t.project)).slice(0, 40).map(x => [x.id, x.title.slice(0, 40)]) }], onSubmit: v => { DB.set('tasks', t.id, { deps: v.deps }, { action: 'dependencies' }); refreshOverlays(); render(); } }); };
ACT['task.recur'] = el => { const t = DB.get('tasks', el.dataset.id); openForm({ title: 'Recurring task', vals: { freq: t.recur?.freq || 'weekly', next: t.recur?.next || addDays(today(), 7) }, fields: [{ n: 'freq', l: 'Repeats', t: 'select', blank: 'Does not repeat', o: [['daily', 'Daily'], ['weekly', 'Weekly'], ['monthly', 'Monthly']] }, { n: 'next', l: 'Next occurrence', t: 'date', min: today() }], onSubmit: v => { DB.set('tasks', t.id, { recur: v.freq ? { freq: v.freq, next: v.next } : null }, { action: 'recurring' }); refreshOverlays(); render(); } }); };
ACT['timer.start'] = el => { const u = me(); if (u.timer) { return toast('A timer is already running. Stop it first.', 'warn'); } DB.set('users', u.id, { timer: { taskId: el.dataset.id, start: Date.now() } }, { quiet: true }); refreshOverlays(); toast('Timer started'); };
ACT['timer.stop'] = () => { const u = me(); const tm = u.timer; if (!tm) return; const h = Math.max(0.1, Math.round((Date.now() - tm.start) / 36e5 * 10) / 10); DB.add('timelogs', { taskId: tm.taskId, userId: u.id, date: today(), hours: h, note: 'Timer' }, { quiet: true }); DB.set('users', u.id, { timer: null }, { quiet: true }); refreshOverlays(); toast(h + ' h logged'); };
ACT['time.add'] = el => openForm({ title: 'Add time', fields: [{ n: 'hours', l: 'Hours', t: 'number', req: true, min: 0.1, step: '0.1', half: true }, { n: 'date', l: 'Date', t: 'date', req: true, half: true, v: today() }, { n: 'note', l: 'Note' }], onSubmit: v => { DB.add('timelogs', { taskId: el.dataset.id, userId: SESS.uid, date: v.date, hours: v.hours, note: v.note || '' }, { quiet: true }); refreshOverlays(); render(); } });

/* ----- board ----- */
function workBoard() {
  const ts = visibleTasks().filter(t => !UI.taskMine || t.assignee === SESS.uid); const prj = UI.boardProject || '';
  return `<div class="row" style="margin-bottom:12px"><label class="chip"><select data-on="work.bproj" aria-label="Project">${opts(DB.q('projects').filter(p => !p.template).map(p => [p.id, p.name]), prj, 'All projects')}</select></label><div class="row" style="gap:4px"><button class="btn sm ${!UI.taskMine ? 'dark' : ''}" data-act="task.mine" data-v="">Everyone</button><button class="btn sm ${UI.taskMine ? 'dark' : ''}" data-act="task.mine" data-v="1">Mine</button></div><span class="sp"></span><span class="small muted">Drag cards to change status</span></div><div class="board" style="grid-auto-columns:minmax(260px,1fr)">${TASK_ST.map(([k, l]) => { const items = ts.filter(t => t.status === k && (!prj || t.project === prj)).sort(by(t => t.due || '9')); return `<div class="col" data-tstatus="${k}"><div class="chd"><b style="font-weight:500">${l}</b><span class="n">${items.length}</span></div>${items.map(t => `<div class="kc" draggable="true" data-task="${t.id}" data-act="task.open" data-id="${t.id}"><b>${esc(t.title)}</b><span class="small muted">${esc(DB.get('projects', t.project)?.name || 'No project')}</span><div class="meta">${avatar(userName(t.assignee), 'sm')}${spill(t.priority)}${t.due ? `<span style="${t.due < today() && k !== 'done' ? 'color:var(--harvest)' : ''}">${fmtDate(t.due)}</span>` : ''}</div></div>`).join('') || '<div class="small muted" style="padding:8px">Nothing here</div>'}</div>`; }).join('')}</div>`;
}
ACT['work.bproj'] = el => { UI.boardProject = el.value; render(); }; ACT['task.open'] = el => openTask(el.dataset.id);
document.addEventListener('dragstart', e => { const c = e.target.closest?.('.kc[data-task]'); if (c) { e.dataTransfer.setData('text/task', c.dataset.task); e.dataTransfer.effectAllowed = 'move'; } });
document.addEventListener('dragover', e => { const c = e.target.closest?.('.col[data-tstatus]'); if (c) { e.preventDefault(); c.classList.add('over'); } });
document.addEventListener('dragleave', e => { e.target.closest?.('.col[data-tstatus]')?.classList.remove('over'); });
document.addEventListener('drop', e => { const c = e.target.closest?.('.col[data-tstatus]'); if (!c) return; e.preventDefault(); c.classList.remove('over'); const id = e.dataTransfer.getData('text/task'); const t = id && DB.get('tasks', id); if (t && (can('task.manage') || t.assignee === SESS.uid || t.cby === SESS.uid)) { setTaskStatus(id, c.dataset.tstatus); render(); } else if (t) toast('Only the assignee or a manager can move this task.', 'warn'); });

/* ----- calendar, gantt ----- */
function workCalendar() { const ts = visibleTasks().filter(t => t.due); const ev = ts.map(t => ({ d: t.due, t: t.title, act: 'task.open', id: t.id, cls: t.status === 'done' ? '' : t.due < today() ? 'w' : 'i' })); return card('Due dates', calendarHtml('taskcal', ev), { ic: 'calendar' }); }
function workGantt() {
  const prj = UI.ganttProject || ''; const ts = visibleTasks().filter(t => t.due && (!prj || t.project === prj)).map(t => ({ ...t, s: t.start || addDays(t.due, -2) })).sort(by(t => t.s)).slice(0, 40);
  if (!ts.length) return emptyState('No dated tasks to show.', 'gantt');
  const min = ts.reduce((m, t) => t.s < m ? t.s : m, ts[0].s), max = ts.reduce((m, t) => t.due > m ? t.due : m, ts[0].due); const from = addDays(min, -2), total = Math.max(daysBetween(from, addDays(max, 3)), 14); const pos = d => Math.max(0, daysBetween(from, d) / total * 100); const ticks = []; for (let i = 0; i <= total; i += Math.ceil(total / 10)) ticks.push(i);
  return `<div class="row" style="margin-bottom:12px"><label class="chip"><select data-on="work.gproj" aria-label="Project">${opts(DB.q('projects').filter(p => !p.template).map(p => [p.id, p.name]), prj, 'All projects')}</select></label><span class="sp"></span><span class="small muted">Bars run from start to due date. Orange means overdue.</span></div><div class="gantt"><div style="min-width:760px"><div class="gr gh" style="grid-template-columns:230px 1fr"><div class="gl">Task</div><div class="gb">${ticks.map(i => `<span style="left:${i / total * 100}%">${fmtDate(addDays(from, i)).slice(0, 6)}</span>`).join('')}</div></div>${ts.map(t => `<div class="gr" style="grid-template-columns:230px 1fr"><div class="gl" title="${esc(t.title)}">${esc(t.title)}${(t.deps || []).length ? ` <span class="muted">· after ${t.deps.length}</span>` : ''}</div><div class="gb">${today() >= from ? `<span class="today" style="left:${pos(today())}%"></span>` : ''}<i class="${t.status === 'done' ? 'done' : t.due < today() ? 'late' : ''}" style="left:${pos(t.s)}%;width:${Math.max(2.5, pos(addDays(t.due, 1)) - pos(t.s))}%;cursor:pointer" data-act="task.open" data-id="${t.id}">${esc(userName(t.assignee).split(' ')[0])}</i></div></div>`).join('')}</div></div>`;
}
ACT['work.gproj'] = el => { UI.ganttProject = el.value; render(); };

/* ----- projects (OPS-01) ----- */
function workProjects() {
  const rows = () => DB.q('projects').filter(p => !p.template).map(p => { const ts = DB.q('tasks').filter(t => t.project === p.id); return { ...p, ownerName: userName(p.owner), nt: ts.length, done: ts.filter(t => t.status === 'done').length, od: ts.filter(t => t.status !== 'done' && t.due < today()).length }; });
  const tpls = DB.q('projects').filter(p => p.template);
  return table({ id: 'projects', title: 'Projects', rows, ph: 'Search projects', onRow: p => go('work/project/' + p.id), filters: [{ k: 'status', l: 'Status', o: ['Planned', 'Active', 'On hold', 'Completed'], get: p => p.status }], tools: `${can('admin.config') || can('task.manage') ? `<button class="btn sm" data-act="adm.zoho">${icon('upload', 'sm')} Import from Zoho Projects</button>` : ''}<button class="btn sm" data-act="prj.tpl">From template${tpls.length ? ' (' + tpls.length + ')' : ''}</button><button class="btn sm primary" data-act="prj.new">${icon('plus', 'sm')} New project</button>`, cols: [{ k: 'name', l: 'Project', r: p => `<div class="cellmain"><b>${esc(p.name)}</b><span>${esc(p.dept || '')}${p.kind ? ' · site works' : ''}</span></div>`, x: p => p.name }, { k: 'ownerName', l: 'Owner' }, { k: 'due', l: 'Due', r: p => fmtDate(p.due), sv: p => p.due }, { k: 'p', l: 'Progress', sv: p => p.nt ? p.done / p.nt : 0, r: p => `<div style="width:130px">${progress(p.done, p.nt || 1)}<div class="small muted">${p.done}/${p.nt} tasks${p.od ? ' · ' + p.od + ' overdue' : ''}</div></div>`, x: p => p.done + '/' + p.nt }, { k: 'status', l: 'Status', r: p => spill(p.status, p.status === 'Completed' ? 'ok' : p.status === 'Active' ? 'warn' : '') }] });
}
const prjFields = [{ n: 'name', l: 'Project name', req: true }, { n: 'desc', l: 'Description', t: 'textarea' }, { n: 'owner', l: 'Owner', t: 'select', req: true, o: () => coUsers().map(u => [u.id, u.name]), blank: false, half: true }, { n: 'dept', l: 'Department', t: 'select', o: () => DB.q('depts').map(d => d.name), half: true }, { n: 'start', l: 'Start', t: 'date', req: true, half: true }, { n: 'due', l: 'Due', t: 'date', req: true, half: true }, { n: 'status', l: 'Status', t: 'select', blank: false, o: ['Planned', 'Active', 'On hold', 'Completed'], half: true }, { n: 'kind', l: 'Type', t: 'select', blank: false, o: [['', 'General project'], ['estate-dev', 'Estate development (contractors, budget, photos)']], half: true }, { n: 'team', l: 'Team', t: 'multi', o: () => coUsers().map(u => [u.id, u.name.split(' ')[0]]) }];
const resolveFields = f => f.map(x => ({ ...x, o: typeof x.o === 'function' && !['show'].includes(x.n) ? x.o() : x.o }));
ACT['prj.new'] = () => openForm({ title: 'New project', fields: resolveFields(prjFields), vals: { owner: SESS.uid, start: today(), due: addDays(today(), 30), status: 'Active', team: [SESS.uid] }, onSubmit: v => { const p = DB.add('projects', { ...v, milestones: [], budget: 0, costs: [], photos: [], comments: [] }); go('work/project/' + p.id); } });
ACT['prj.tpl'] = () => { const tpls = DB.q('projects').filter(p => p.template); if (!tpls.length) return toast('No templates yet. Open a project and choose Save as template.', 'warn'); openForm({ title: 'New project from template', fields: [{ n: 't', l: 'Template', t: 'select', req: true, o: tpls.map(p => [p.id, p.name]) }, { n: 'name', l: 'Project name', req: true }, { n: 'start', l: 'Start', t: 'date', req: true, v: today() }, { n: 'owner', l: 'Owner', t: 'select', blank: false, o: coUsers().map(u => [u.id, u.name]), v: SESS.uid }], vals: { start: today(), owner: SESS.uid }, onSubmit: v => { const tp = DB.get('projects', v.t); const p = DB.add('projects', { name: v.name, desc: tp.desc, owner: v.owner, dept: tp.dept, status: 'Active', start: v.start, due: addDays(v.start, tp.span || 30), team: [v.owner], milestones: (tp.milestones || []).map(m => ({ n: m.n, d: addDays(v.start, m.off || 0), done: false })), kind: tp.kind || '', budget: 0, costs: [], photos: [], comments: [] }); (tp.blueprint || []).forEach(b => DB.add('tasks', { title: b.title, project: p.id, assignee: v.owner, due: addDays(v.start, b.off), start: addDays(v.start, Math.max(0, b.off - 2)), priority: 'Medium', status: 'todo', followers: [], subtasks: [], checklist: [], comments: [], history: [], deps: [] }, { quiet: true })); toast('Project created with ' + (tp.blueprint || []).length + ' tasks'); go('work/project/' + p.id); } }); };
function projectPage(id) {
  const p = DB.get('projects', id); if (!p) return card('Project not found', '<a class="btn" href="#/work/projects">Back</a>');
  const ts = DB.q('tasks').filter(t => t.project === id); const done = ts.filter(t => t.status === 'done').length; const iss = DB.q('issues').filter(i => i.projectId === id); const logged = sum(DB.q('timelogs').filter(l => ts.some(t => t.id === l.taskId)), l => l.hours); const manage = can('task.manage') || p.owner === SESS.uid;
  const costs = p.costs || []; const spent = sum(costs, c => c.amount);
  return pageHead({ title: esc(p.name), sub: `${esc(p.desc || '')} · owner ${esc(userName(p.owner))} · ${fmtDate(p.start)} – ${fmtDate(p.due)}`, acts: `<a class="btn" href="#/work/projects">${icon('chevl', 'sm')} Projects</a>${manage ? `<button class="btn" data-act="prj.edit" data-id="${id}">${icon('edit', 'sm')} Edit</button><button class="btn" data-act="prj.saveTpl" data-id="${id}">Save as template</button><button class="btn primary" data-act="task.newp" data-id="${id}">${icon('plus', 'sm')} Add task</button>` : ''}` }) +
    `<div class="grid g4" style="margin-bottom:16px">${tile({ ic: 'clipboard', title: 'Tasks done', value: done, unit: '/ ' + ts.length, caps: { v: done, max: ts.length || 1 } })}${tile({ cls: 'tea', ic: 'warn', title: 'Overdue', value: ts.filter(t => t.status !== 'done' && t.due < today()).length })}${tile({ ic: 'clock', title: 'Time logged', value: Math.round(logged), unit: 'hours' })}${tile({ cls: 'dark', ic: 'flag', title: 'Open issues', value: iss.filter(i => i.status !== 'Resolved').length })}</div>
    <div class="grid g21" style="align-items:start"><div class="stack">${card('Tasks', ts.length ? `<table class="tbl"><thead><tr><th>Task</th><th>Assignee</th><th>Due</th><th>Status</th></tr></thead><tbody>${ts.sort(by(t => t.due || '9')).map(t => `<tr class="clk" data-act="task.open" data-id="${t.id}"><td>${esc(t.title)}</td><td>${esc(userName(t.assignee))}</td><td>${fmtDate(t.due)}</td><td>${spill(stLabel(t.status))}</td></tr>`).join('')}</tbody></table>` : emptyState('No tasks yet.'), { ic: 'clipboard' })}${card('Discussion', `<div class="stack" style="gap:10px">${(p.comments || []).map(c => `<div class="row" style="align-items:flex-start">${avatar(userName(c.by), 'sm')}<div><b style="font-weight:500">${esc(userName(c.by))}</b> <span class="small muted">${ago(c.ts)}</span><div style="white-space:pre-wrap">${mentionHtml(c.text)}</div></div></div>`).join('') || '<span class="muted small">No messages yet.</span>'}</div><form style="margin-top:12px" data-submit="prj.comment" data-id="${id}"><label class="chip" style="width:100%"><input name="t" placeholder="Post to the project thread. @mention teammates" aria-label="Project message"></label></form>`, { ic: 'chat' })}
    ${p.kind ? card('Site costs and budget', `<div class="row" style="margin-bottom:10px"><div class="stat"><b>${money(spent)}</b><span>spent of ${money(p.budget || 0)} budget</span></div><span class="sp"></span>${manage ? `<button class="btn sm" data-act="prj.budget" data-id="${id}">Set budget</button><button class="btn sm primary" data-act="prj.cost" data-id="${id}">Add cost</button>` : ''}</div>${progress(spent, p.budget || 1, spent > (p.budget || 0) * .85)}${costs.length ? `<table class="tbl" style="margin-top:10px"><thead><tr><th>Contractor</th><th>Work</th><th>Date</th><th class="num">Amount</th></tr></thead><tbody>${costs.map(c => `<tr><td>${esc(c.contractor)}</td><td>${esc(c.desc)}</td><td>${fmtDate(c.date)}</td><td class="num">${money(c.amount)}</td></tr>`).join('')}</tbody></table>` : ''}`, { ic: 'coins' }) : ''}
    ${p.kind ? card('Site photos', `<div class="grid g3" style="gap:10px">${(p.photos || []).map(ph => `<img src="${ph.url}" alt="${esc(ph.cap)}" style="width:100%;height:120px;object-fit:cover;border-radius:12px">`).join('') || '<span class="muted">No photos yet.</span>'}</div>${manage ? `<button class="btn sm" style="margin-top:10px" data-act="prj.photo" data-id="${id}">${icon('image', 'sm')} Add photo</button>` : ''}`, { ic: 'image' }) : ''}</div>
    <div class="stack">${card('Milestones', `${(p.milestones || []).map((m, i) => `<label class="row" style="gap:10px;padding:5px 0"><input type="checkbox" data-act="ms.toggle" data-id="${id}" data-i="${i}" ${m.done ? 'checked' : ''} ${manage ? '' : 'disabled'}><span class="grow">${esc(m.n)}</span><span class="small muted">${fmtDate(m.d)}</span></label>`).join('') || '<span class="muted">None.</span>'}${manage ? `<button class="btn sm" style="margin-top:8px" data-act="ms.add" data-id="${id}">Add milestone</button>` : ''}`, { ic: 'flag' })}${card('Team', (p.team || []).map(u => `<div style="padding:4px 0">${userChip(u)}</div>`).join('') || '<span class="muted">No team.</span>', { ic: 'users' })}${card('Issues', iss.map(i => `<a class="tilebtn" style="margin-bottom:6px" href="#/work/issues?i=${i.id}">${icon('flag')}<span class="grow">${esc(i.title)}</span>${spill(i.severity)}</a>`).join('') || '<span class="muted">None logged.</span>', { ic: 'warn' })}</div></div>`;
}
ACT['task.newp'] = el => { const p = DB.get('projects', el.dataset.id); openForm({ title: 'Add task to ' + esc(p.name), fields: taskFields(), vals: { project: p.id, assignee: SESS.uid, priority: 'Medium', due: addDays(today(), 3) }, onSubmit: v => { DB.add('tasks', { ...v, followers: [], status: 'todo', subtasks: [], checklist: [], comments: [], history: [{ ts: Date.now(), by: SESS.uid, what: 'Created task' }], deps: [] }); notify(v.assignee, 'Task assigned to you: ' + v.title, p.name, '#/work/tasks'); render(); } }); };
ACT['prj.edit'] = el => { const p = DB.get('projects', el.dataset.id); openForm({ title: 'Edit project', fields: resolveFields(prjFields), vals: p, onSubmit: v => { DB.set('projects', p.id, v); render(); } }); };
ACT['prj.saveTpl'] = el => { const p = DB.get('projects', el.dataset.id); const ts = DB.q('tasks').filter(t => t.project === p.id); askText('Save as template', 'Template name', n => { DB.add('projects', { name: n, desc: p.desc, dept: p.dept, owner: p.owner, status: 'Planned', template: true, kind: p.kind, span: Math.max(7, daysBetween(p.start, p.due)), milestones: (p.milestones || []).map(m => ({ n: m.n, off: Math.max(0, daysBetween(p.start, m.d)) })), blueprint: ts.map(t => ({ title: t.title, off: Math.max(0, daysBetween(p.start, t.due || p.due)) })), team: [], start: p.start, due: p.due }); toast('Template saved'); }, { t: 'text', vals: { v: p.name + ' template' }, submit: 'Save template' }); };
